                 //                 { "currency": "usdt", "type": "trade",
                 //                 "balance": "100" }, { "currency": "usdt",
                 //                 "type": "frozen", "balance": "0" }, {
                 //                 "currency": "usdt", "type":
                 //                 "loan-available", "balance": "200" }, {
                 //                 "currency": "usdt", "type":
                 //                 "transfer-out-available", "balance": "-1" },
                 //                 { "currency": "ht", "type":
