  virtual std::shared_future<ccxt::any> fetchContractOrders(
      ccxt::any symbol = ccxt::any{}, ccxt::any since = ccxt::any{},
      ccxt::any limit = ccxt::any{}, ccxt::any params = ccxt::dict{}) {
    return std::
        async(std::launch::deferred,
              [=]() mutable -> ccxt::any {
                if (isTrue(isEqual(symbol, ccxt::any{}))) {
                  throw ArgumentsRequired(toString(add(
                      this->id, std::string(" fetchContractOrders() requires a "
                                            "symbol argument"))));
                }
                if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                  awaitValue(this->loadMarkets());
                }
                ccxt::any market = this->market(symbol);
                ccxt::any request = ccxt::dict{};
                ccxt::any response = ccxt::any{};
                ccxt::any trigger = this->safeBool2(params, std::string("stop"),
                                                    std::string("trigger"));
                ccxt::any stopLossTakeProfit =
                    this->safeValue(params, std::string("stopLossTakeProfit"));
                ccxt::any stopLoss =
                    this->safeBool(params, std::string("stopLoss"));
                ccxt::any takeProfit =
                    this->safeBool(params, std::string("takeProfit"));
                ccxt::any trailing =
                    this->safeBool(params, std::string("trailing"), false);
                ccxt::any isAlgo =
                    (isTrue(isTrue(isTrue(isTrue((isEqual(trigger, true))) ||
                                          isTrue((isEqual(stopLoss, true)))) ||
                                   isTrue((isEqual(takeProfit, true)))) ||
                            isTrue((isEqual(stopLossTakeProfit, true)))) ||
                     isTrue((isEqual(trailing, true))));
                params = this->omit(
                    params,
                    ccxt::list{
                        std::string("stop"), std::string("stopLossTakeProfit"),
                        std::string("trailing"), std::string("trigger"),
                        std::string("stopLoss"), std::string("takeProfit")});
                if (isTrue(!isEqual(since, ccxt::any{}))) {
                  ::setValue(request, std::string("start_time"), since);
                }
                ccxt::any requestparamsVariable = this->handleUntilOption(
                    std::string("end_time"), request, params);
                request = ::getValue(requestparamsVariable, 0);
                params = ::getValue(requestparamsVariable, 1);
                if (isTrue(isEqual(::getValue(market, std::string("linear")),
                                   true))) {
                  if (isTrue(!isEqual(limit, ccxt::any{}))) {
                    ::setValue(request, std::string("limit"), limit);
                  }
                  ccxt::any marginMode = ccxt::any{};
                  ccxt::any marginModeparamsVariable =
                      this->handleMarginModeAndParams(
                          std::string("fetchContractOrders"), params);
                  marginMode = ::getValue(marginModeparamsVariable, 0);
                  params = ::getValue(marginModeparamsVariable, 1);
                  marginMode = (isTrue((isEqual(marginMode, ccxt::any{})))
                                    ? ccxt::any(std::string("cross"))
                                    : ccxt::any(marginMode));
                  ::setValue(request, std::string("margin_mode"), marginMode);
                  ::setValue(request, std::string("contract_code"),
                             ::getValue(market, std::string("id")));
                  if (isTrue(isEqual(isAlgo, true))) {
                    if (isTrue(isEqual(trigger, true))) {
                      ::setValue(request, std::string("type"),
                                 std::string("trigger"));
                    } else if (isTrue(isEqual(trailing, true))) {
                      ::setValue(request, std::string("type"),
                                 std::string("trailing_stop"));
                    } else if (isTrue(isEqual(stopLossTakeProfit, true))) {
                      ::setValue(request, std::string("type"),
                                 std::string("tpsl"));
                    } else if (isTrue(isEqual(stopLoss, true))) {
                      ::setValue(request, std::string("type"),
                                 std::string("sl"));
                    } else if (isTrue(isEqual(takeProfit, true))) {
                      ::setValue(request, std::string("type"),
                                 std::string("tp"));
                    }
                    response =
                        awaitValue(this->contractPrivateGetV5AlgoOrderHistory(
                            this->extend(request, params)));
                  } else {
                    response =
                        awaitValue(this->contractPrivateGetV5TradeOrderHistory(
                            this->extend(request, params)));
                  }
                } else if (isTrue(isEqual(
                               ::getValue(market, std::string("inverse")),
                               true))) {
                  ::setValue(request, std::string("contract"),
                             ::getValue(market, std::string("id")));
                  ::setValue(request, std::string("type"),
                             1); // 1:All Orders,2:Order in Finished Status
                  ::setValue(request, std::string("trade_type"),
                             0); // 0:All; 1: Open long; 2: Open short; 3: Close
                                 // short; 4: Close long; 5: Liquidate long
                                 // positions; 6: Liquidate short positions,
                                 // 17:buy(one-way mode), 18:sell(one-way mode)
                  ::setValue(
                      request, std::string("status"),
                      std::string(
                          "0")); // support multiple query separated by ',',such
                                 // as '3,4,5', 0: all. 3. Have submitted the
                                 // orders; 4. Orders partially matched; 5.
                                 // Orders cancelled with partially matched; 6.
                                 // Orders fully matched; 7. Orders cancelled;
                  if (isTrue(isEqual(::getValue(market, std::string("swap")),
                                     true))) {
                    if (isTrue(isEqual(trigger, true))) {
                      response = awaitValue(
                          this->contractPrivatePostSwapApiV1SwapTriggerHisorders(
                              this->extend(request, params)));
                    } else if (isTrue(isEqual(stopLossTakeProfit, true))) {
                      response = awaitValue(
                          this->contractPrivatePostSwapApiV1SwapTpslHisorders(
                              this->extend(request, params)));
                    } else if (isTrue(isEqual(trailing, true))) {
                      response = awaitValue(
                          this->contractPrivatePostSwapApiV1SwapTrackHisorders(
                              this->extend(request, params)));
                    } else {
                      response = awaitValue(
                          this->contractPrivatePostSwapApiV3SwapHisorders(
                              this->extend(request, params)));
                    }
                  } else if (isTrue(isEqual(
                                 ::getValue(market, std::string("future")),
                                 true))) {
                    ::setValue(request, std::string("symbol"),
                               ::getValue(market, std::string("settleId")));
                    if (isTrue(isEqual(trigger, true))) {
                      response = awaitValue(
                          this->contractPrivatePostApiV1ContractTriggerHisorders(
                              this->extend(request, params)));
                    } else if (isTrue(isEqual(stopLossTakeProfit, true))) {
                      response = awaitValue(
                          this->contractPrivatePostApiV1ContractTpslHisorders(
                              this->extend(request, params)));
                    } else if (isTrue(isEqual(trailing, true))) {
                      response = awaitValue(
                          this->contractPrivatePostApiV1ContractTrackHisorders(
                              this->extend(request, params)));
                    } else {
                      response = awaitValue(
                          this->contractPrivatePostApiV3ContractHisorders(
                              this->extend(request, params)));
                    }
                  }
                }
                ccxt::any orders =
                    this->safeValue(response, std::string("data"));
                if (!isTrue(isArray(orders))) {
                  orders = this->safeValue(orders, std::string("orders"),
                                           ccxt::list{});
                }
                return this->parseOrders(orders, market, since, limit);
              })
            .share();
  }

  virtual std::shared_future<ccxt::any> fetchClosedContractOrders(
      ccxt::any symbol = ccxt::any{}, ccxt::any since = ccxt::any{},
      ccxt::any limit = ccxt::any{}, ccxt::any params = ccxt::dict{}) {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 if (isTrue(isEqual(symbol, ccxt::any{}))) {
                   throw ArgumentsRequired(toString(add(
                       this->id, std::string(" fetchClosedContractOrders() "
                                             "requires a symbol argument"))));
                 }
                 if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 ccxt::any request = ccxt::dict{};
                 ccxt::any market = this->market(symbol);
                 if (isTrue(isEqual(::getValue(market, std::string("linear")),
                                    true))) {
                   ccxt::any trigger = this->safeBool2(
                       params, std::string("stop"), std::string("trigger"));
                   ccxt::any stopLossTakeProfit = this->safeValue(
                       params, std::string("stopLossTakeProfit"));
                   ccxt::any stopLoss =
                       this->safeBool(params, std::string("stopLoss"));
                   ccxt::any takeProfit =
                       this->safeBool(params, std::string("takeProfit"));
                   ccxt::any trailing =
                       this->safeBool(params, std::string("trailing"), false);
                   ccxt::any isAlgo =
                       (isTrue(
                            isTrue(isTrue(isTrue((isEqual(trigger, true))) ||
                                          isTrue((isEqual(stopLoss, true)))) ||
                                   isTrue((isEqual(takeProfit, true)))) ||
                            isTrue((isEqual(stopLossTakeProfit, true)))) ||
                        isTrue((isEqual(trailing, true))));
                   if (isTrue(isEqual(isAlgo, true))) {
                     ::setValue(request, std::string("states"),
                                std::string("effective"));
                   } else {
                     ::setValue(request, std::string("states"),
                                std::string("filled"));
                   }
                 } else {
                   ::setValue(request, std::string("status"), std::string("6"));
                 }
                 return awaitValue(this->fetchContractOrders(
                     symbol, since, limit, this->extend(request, params)));
               })
        .share();
  }

  /**
   * @method
   * @name htx#fetchOrders
   * @description fetches information on multiple orders made by the user
   * @see https://huobiapi.github.io/docs/spot/v1/en/#search-past-orders
   * @see
   * https://huobiapi.github.io/docs/spot/v1/en/#search-historical-orders-within-48-hours
   * @see
   * https://www.htx.com/en-us/opend/newApiPages/?id=8cb89359-77b5-11ed-9966-19589bc57bc
   * @see
   * https://www.htx.com/en-us/opend/newApiPages/?id=8cb89359-77b5-11ed-9966-19b979b0aa2
   * @see
   * https://huobiapi.github.io/docs/coin_margined_swap/v1/en/#get-history-orders-new
   * @see
   * https://huobiapi.github.io/docs/coin_margined_swap/v1/en/#query-history-orders-via-multiple-fields-new
   * @param {string} symbol unified market symbol of the market orders were made
   * in
   * @param {int} [since] the earliest time in ms to fetch orders for
   * @param {int} [limit] the maximum number of order structures to retrieve
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {int} [params.until] the latest time in ms to fetch entries for
   * @param {bool} [params.trigger] *contract only* if the orders are trigger
   * trigger orders or not
   * @param {bool} [params.trailing] *contract only* set to true if you want to
   * fetch trailing stop orders
   * @param {bool} [params.stopLossTakeProfit] *contract only* if the orders are
   * stop-loss and take-profit orders
   * @param {bool} [params.stopLoss] *contract only* set to true if you want to
   * fetch stop loss orders
   * @param {bool} [params.takeProfit] *contract only* set to true if you want
   * to fetch take profit orders
   * @returns {Order[]} a list of [order structures]{@link
   * https://docs.ccxt.com/?id=order-structure}
   */
  std::shared_future<ccxt::any>
  fetchOrders(ccxt::any symbol = ccxt::any{}, ccxt::any since = ccxt::any{},
              ccxt::any limit = ccxt::any{},
              ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 ccxt::any market = ccxt::any{};
                 if (isTrue(!isEqual(symbol, ccxt::any{}))) {
                   market = this->market(symbol);
                 }
                 ccxt::any marketType = ccxt::any{};
                 ccxt::any marketTypeparamsVariable =
                     this->handleMarketTypeAndParams(std::string("fetchOrders"),
                                                     market, params);
                 marketType = ::getValue(marketTypeparamsVariable, 0);
                 params = ::getValue(marketTypeparamsVariable, 1);
                 ccxt::any contract =
                     isTrue((isEqual(marketType, std::string("swap")))) ||
                     isTrue((isEqual(marketType, std::string("future"))));
                 if (isTrue(isTrue(contract) &&
                            isTrue((isEqual(symbol, ccxt::any{}))))) {
                   throw ArgumentsRequired(toString(add(
                       add(add(this->id, std::string(" fetchOrders() requires "
                                                     "a symbol argument for ")),
                           marketType),
                       std::string(" orders"))));
                 }
                 if (isTrue(contract)) {
                   return awaitValue(
                       this->fetchContractOrders(symbol, since, limit, params));
                 } else {
                   return awaitValue(
                       this->fetchSpotOrders(symbol, since, limit, params));
                 }
                 return ccxt::any{};
               })
        .share();
  }

  /**
   * @method
   * @name htx#fetchCanceledOrders
   * @description fetches information on multiple canceled orders made by the
   * user
   * @see https://huobiapi.github.io/docs/spot/v1/en/#search-past-orders
   * @see
   * https://huobiapi.github.io/docs/spot/v1/en/#search-historical-orders-within-48-hours
   * @see
   * https://www.htx.com/en-us/opend/newApiPages/?id=8cb89359-77b5-11ed-9966-19589bc57bc
   * @see
   * https://www.htx.com/en-us/opend/newApiPages/?id=8cb89359-77b5-11ed-9966-19b979b0aa2
   * @see
   * https://huobiapi.github.io/docs/coin_margined_swap/v1/en/#get-history-orders-new
   * @see
   * https://huobiapi.github.io/docs/coin_margined_swap/v1/en/#query-history-orders-via-multiple-fields-new
   * @param {string} symbol unified market symbol of the market orders were made
   * in
   * @param {int} [since] the earliest time in ms to fetch orders for
   * @param {int} [limit] the maximum number of order structures to retrieve
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {int} [params.until] the latest time in ms to fetch entries for
   * @param {boolean} [params.paginate] default false, when true will
   * automatically paginate by calling this endpoint multiple times. See in the
   * docs all the [available
   * parameters](https://github.com/ccxt/ccxt/wiki/Manual#pagination-params)
   * @returns {Order[]} a list of [order structures]{@link
   * https://docs.ccxt.com/?id=order-structure}
   */
  std::shared_future<ccxt::any> fetchCanceledOrders(
      ccxt::any symbol = ccxt::any{}, ccxt::any since = ccxt::any{},
      ccxt::any limit = ccxt::any{}, ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 ccxt::any paginate = false;
                 ccxt::any paginateparamsVariable = this->handleOptionAndParams(
                     params, std::string("fetchCanceledOrders"),
                     std::string("paginate"));
                 paginate = ::getValue(paginateparamsVariable, 0);
                 params = ::getValue(paginateparamsVariable, 1);
                 if (isTrue(paginate)) {
                   return awaitValue(this->fetchPaginatedCallDynamic(
                       std::string("fetchCanceledOrders"), symbol, since, limit,
                       params, 100));
                 }
                 ccxt::any market = ccxt::any{};
                 if (isTrue(!isEqual(symbol, ccxt::any{}))) {
                   market = this->market(symbol);
                 }
                 ccxt::any marketType = ccxt::any{};
                 ccxt::any marketTypeparamsVariable =
                     this->handleMarketTypeAndParams(
                         std::string("fetchCanceledOrders"), market, params);
                 marketType = ::getValue(marketTypeparamsVariable, 0);
                 params = ::getValue(marketTypeparamsVariable, 1);
                 if (isTrue(isEqual(marketType, std::string("spot")))) {
                   return awaitValue(this->fetchSpotOrdersByStates(
                       std::string("partial-canceled,canceled"), symbol, since,
                       limit, params));
                 } else {
                   if (isTrue(isEqual(symbol, ccxt::any{}))) {
                     throw ArgumentsRequired(toString(add(
                         add(add(this->id,
                                 std::string(" fetchCanceledOrders() requires "
                                             "a symbol argument for ")),
                             marketType),
                         std::string(" orders"))));
                   }
                   ccxt::any request = ccxt::dict{};
                   if (isTrue(isEqual(
                           this->safeBool(market, std::string("linear")),
                           true))) {
                     ccxt::any trigger = this->safeBool2(
                         params, std::string("stop"), std::string("trigger"));
                     ccxt::any stopLossTakeProfit = this->safeValue(
                         params, std::string("stopLossTakeProfit"));
                     ccxt::any stopLoss =
                         this->safeBool(params, std::string("stopLoss"));
                     ccxt::any takeProfit =
                         this->safeBool(params, std::string("takeProfit"));
                     ccxt::any trailing =
                         this->safeBool(params, std::string("trailing"), false);
                     ccxt::any isAlgo =
                         (isTrue(
                              isTrue(
                                  isTrue(isTrue((isEqual(trigger, true))) ||
                                         isTrue((isEqual(stopLoss, true)))) ||
                                  isTrue((isEqual(takeProfit, true)))) ||
                              isTrue((isEqual(stopLossTakeProfit, true)))) ||
                          isTrue((isEqual(trailing, true))));
                     if (isTrue(isEqual(isAlgo, true))) {
                       ::setValue(request, std::string("states"),
                                  std::string("canceled"));
                     } else {
                       ::setValue(request, std::string("states"),
                                  std::string("partially_canceled,canceled"));
                     }
                   } else {
                     ::setValue(
                         request, std::string("status"),
                         std::string(
                             "5,7")); // comma separated, 0 all, 3 submitted
                                      // orders, 4 partially matched, 5
                                      // partially cancelled, 6 fully matched
                                      // and closed, 7 canceled
                   }
                   return awaitValue(this->fetchContractOrders(
                       symbol, since, limit, this->extend(request, params)));
                 }
                 return ccxt::any{};
               })
        .share();
  }

