                //                     "direction": "buy",
                //                     "offset": "close",
                //                     "lever_rate": 20,
                //                     "order_id": 773131315209248768,
                //                     "client_order_id": null,
                //                     "created_at": 1604370469629,
                //                     "trade_volume": 0,
                //                     "trade_turnover": 0,
                //                     "fee": 0,
                //                     "trade_avg_price": null,
                //                     "margin_frozen": 0,
                //                     "profit": 0,
                //                     "status": 3,
                //                     "order_source": "web",
                //                     "order_id_str": "773131315209248768",
                //                     "fee_asset": "ADA",
                //                     "liquidation_type": null,
                //                     "canceled_at": null,
                //                     "is_tpsl": 0,
                //                     "update_time": 1606975980467,
