  virtual ccxt::any parseOrderStatus(ccxt::any status) {
    ccxt::any statuses = ccxt::dict{
        {std::string("partial-filled"), std::string("open")},
        {std::string("partial-canceled"), std::string("canceled")},
        {std::string("filled"), std::string("closed")},
        {std::string("canceled"), std::string("canceled")},
        {std::string("submitted"), std::string("open")},
        {std::string("created"), std::string("open")},
        {std::string("1"), std::string("open")},
        {std::string("2"), std::string("open")},
        {std::string("3"), std::string("open")},
        {std::string("4"), std::string("open")},
        {std::string("5"), std::string("canceled")},
        {std::string("6"), std::string("closed")},
        {std::string("7"), std::string("canceled")},
        {std::string("11"), std::string("canceling")},
        {std::string("active"), std::string("open")},
        {std::string("new"), std::string("open")},
        {std::string("partially_filled"), std::string("open")},
        {std::string("partially_canceled"), std::string("canceled")},
    };
    return this->safeString(statuses, status, status);
  }

